// Fits the guardian dogs generated by scripts/guardians/generate.py (scripts/guardians/out/<id>/) to the 사주 village
// and writes them where the app serves them: public/gltf/guardians/<id>.glb. Every dog comes out one unit tall,
// standing on the origin and facing +z (the scene sizes and places it), with one matte material, a WebP colour map and
// a mesh light enough for a figure never seen close.
// Usage: node scripts/guardians-normalize.mjs [ids...]    (default: every generated model)
// scripts/guardians/models.json says which of a dog's two models is kept (`views`: the ones made from drawn views,
// model-views.glb; the rest are made from the picture itself, model.glb) and turns one that came out facing another
// way (`yaw`: { "07": 180 }).
import { existsSync, mkdirSync, readdirSync, readFileSync, statSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { getBounds, NodeIO } from '@gltf-transform/core';
import { ALL_EXTENSIONS } from '@gltf-transform/extensions';
import { clearNodeTransform, dedup, flatten, join as joinMeshes, meshopt, prune, simplify, textureCompress, weld } from '@gltf-transform/functions';
import { MeshoptDecoder, MeshoptEncoder, MeshoptSimplifier } from 'meshoptimizer';
import sharp from 'sharp';

const frontend = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const source = resolve(frontend, '../scripts/guardians');
const output = join(frontend, 'public/gltf/guardians');
/** A guardian is a metre and a half of a picture many metres wide: a 512 px colour map is plenty. */
const MAP = { resize: [512, 512], quality: 88 };
/** Triangles a dog keeps: its outline stays round at the size it is drawn, and nine of them stand in a village. */
const TRIANGLES = 6000;
/** Fur and cloth: nothing on a dog shines. */
const ROUGHNESS = 0.92;

await Promise.all([MeshoptDecoder.ready, MeshoptEncoder.ready, MeshoptSimplifier.ready]);
const io = new NodeIO()
  .registerExtensions(ALL_EXTENSIONS)
  .registerDependencies({ 'meshopt.decoder': MeshoptDecoder, 'meshopt.encoder': MeshoptEncoder });
const kept = JSON.parse(readFileSync(join(source, 'models.json'), 'utf8'));
const yaws = kept.yaw ?? {};
const modelOf = (id) => join(source, 'out', id, kept.views.includes(id) ? 'model-views.glb' : 'model.glb');

const sceneOf = (document) => document.getRoot().getDefaultScene() ?? document.getRoot().listScenes()[0];
function boxOf(document) {
  const { min, max } = getBounds(sceneOf(document));
  return { min, max, size: max.map((value, axis) => value - min[axis]) };
}
const trianglesOf = (document) =>
  document.getRoot().listMeshes().flatMap((mesh) => mesh.listPrimitives()).reduce((sum, primitive) => sum + (primitive.getIndices()?.getCount() ?? primitive.getAttribute('POSITION').getCount()) / 3, 0);

async function fit(id) {
  const model = modelOf(id);
  if (!existsSync(model)) return `${id}: no generated model`;
  const document = await io.read(model);
  const scene = sceneOf(document);
  const wrapper = document.createNode(`dog-${id}`);
  for (const child of scene.listChildren()) {
    scene.removeChild(child);
    wrapper.addChild(child);
  }
  scene.addChild(wrapper);
  const yaw = ((yaws[id] ?? 0) * Math.PI) / 180;
  wrapper.setRotation([0, Math.sin(yaw / 2), 0, Math.cos(yaw / 2)]);
  const turned = boxOf(document);
  const scale = 1 / turned.size[1];
  wrapper.setScale([scale, scale, scale]);
  wrapper.setTranslation([-((turned.min[0] + turned.max[0]) / 2) * scale, -turned.min[1] * scale, -((turned.min[2] + turned.max[2]) / 2) * scale]);
  for (const material of document.getRoot().listMaterials()) {
    material.setMetallicFactor(0).setMetallicRoughnessTexture(null).setRoughnessFactor(ROUGHNESS).setNormalTexture(null).setOcclusionTexture(null).setEmissiveTexture(null).setEmissiveFactor([0, 0, 0]);
  }
  const before = trianglesOf(document);
  // The fit is written into the vertices themselves: whatever transform the file still carries afterwards only undoes
  // the packing of its numbers (see meshopt below), so a reader takes the scene as it is.
  await document.transform(dedup(), flatten());
  for (const node of document.getRoot().listNodes()) clearNodeTransform(node);
  await document.transform(
    joinMeshes(),
    weld(),
    ...(before > TRIANGLES ? [simplify({ simplifier: MeshoptSimplifier, ratio: TRIANGLES / before, error: 0.004 })] : []),
    prune(),
    textureCompress({ encoder: sharp, targetFormat: 'webp', ...MAP }),
    meshopt({ encoder: MeshoptEncoder, level: 'medium' }),
  );
  mkdirSync(output, { recursive: true });
  const file = join(output, `${id}.glb`);
  await io.write(file, document);
  const fitted = boxOf(document);
  const metres = fitted.size.map((value) => value.toFixed(2)).join(' x ');
  const route = kept.views.includes(id) ? 'from views' : 'from the picture';
  return `${id}: ${metres}, ${Math.round(before)} -> ${Math.round(trianglesOf(document))} triangles, ${(statSync(model).size / 1e6).toFixed(2)} -> ${(statSync(file).size / 1e6).toFixed(2)} MB, ${route}, yaw ${yaws[id] ?? 0}°`;
}

const generated = existsSync(join(source, 'out')) ? readdirSync(join(source, 'out')).filter((id) => existsSync(modelOf(id))).sort() : [];
const wanted = process.argv.slice(2);
const unknown = wanted.filter((id) => !generated.includes(id));
if (unknown.length) throw new Error(`no generated model for: ${unknown.join(', ')}`);
for (const id of wanted.length ? wanted : generated) console.log(await fit(id));
